def solve(nums=None):
    """Return the length of the longest strictly increasing subsequence.
    Handles None or non-iterable inputs by returning 0.
    """
    if nums is None:
        return 0
    # Ensure iterable
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []
    for x in iterator:
        # Only consider int-like values; if not comparable, skip
        try:
            # Find insertion position using bisect_left to maintain increasing
            idx = bisect.bisect_left(tails, x)
        except TypeError:
            # Incomparable element, skip it
            continue
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

